'use strict';
// Adaptación de referencias Figma al mismo sistema visual de Dumbo.
// Todas las operaciones siguen siendo simulaciones en la sesión de la pestaña.
let peopleDeletedView=false;
function accountList(isStaff,deleted=false){return (isStaff?state.staff:state.users).filter(u=>Boolean(u.deleted)===deleted)}
function people(isStaff){
 const list=accountList(isStaff,peopleDeletedView),deleted=peopleDeletedView;
 return `<div class="heading"><div><span class="eyebrow">${isStaff?'Administración':'Atención al cliente'}</span><h1>${isStaff?'Trabajadores':'Clientes'}</h1><p class="muted">Datos de contacto y acceso de las cuentas de ejemplo.</p></div><button onclick="personForm(${isStaff})">Registrar ${isStaff?'trabajador':'cliente'}</button></div>
 <div class="section-tabs" role="group" aria-label="Estado de las cuentas"><button class="${!deleted?'selected':''}" aria-pressed="${!deleted}" onclick="showDeletedPeople(false)">Cuentas vigentes</button><button class="${deleted?'selected':''}" aria-pressed="${deleted}" onclick="showDeletedPeople(true)">Eliminadas (${accountList(isStaff,true).length})</button></div>
 <p class="table-hint">Desliza la tabla para ver las acciones.</p><div class="panel tablewrap" tabindex="0" role="region" aria-label="Listado de ${isStaff?'trabajadores':'clientes'}"><table><thead><tr><th scope="col">Nombre</th><th scope="col">Correo</th><th scope="col">Teléfono</th><th scope="col">Estado</th><th scope="col">Acciones</th></tr></thead><tbody>${list.map(u=>`<tr><td><strong>${esc(fullName(u))}</strong></td><td>${esc(u.email)}</td><td>${esc(u.phone)}</td><td><span class="badge ${u.active&&!deleted?'':'off'}">${deleted?'Eliminada':u.active?'Habilitada':'Deshabilitada'}</span></td><td class="table-actions">${deleted?`<button class="secondary" onclick="restoreAccount(${isStaff},${u.id})">Restaurar<span class="sr-only"> a ${esc(fullName(u))}</span></button>`:`<button class="secondary" onclick="personForm(${isStaff},${u.id})" aria-label="Editar a ${esc(fullName(u))}">Editar</button><button class="secondary" onclick="togglePerson(${isStaff},${u.id})">${u.active?'Deshabilitar':'Habilitar'}<span class="sr-only"> a ${esc(fullName(u))}</span></button><button class="danger" onclick="deleteAccount(${isStaff},${u.id})" aria-label="Eliminar cuenta de ${esc(fullName(u))}">Eliminar</button>`}</td></tr>`).join('')||`<tr><td colspan="5">No hay ${deleted?'cuentas eliminadas':isStaff?'trabajadores':'clientes'} para mostrar.</td></tr>`}</tbody></table></div>
 <p class="muted account-policy">Eliminar retira el acceso y la cuenta del listado vigente. En este prototipo es reversible y conserva los pedidos históricos. No se editan contraseñas desde gestión.</p>`;
}
function showDeletedPeople(value){peopleDeletedView=value;render()}
function allowedAccountAction(isStaff,self=false){return self?state.role==='cliente'&&Boolean(currentUser()):isStaff?state.role==='admin':['trabajador','admin'].includes(state.role)}
function deleteAccount(isStaff,id,self=false){
 const u=(isStaff?state.staff:state.users).find(u=>u.id===id);
 if(!u||u.deleted||!allowedAccountAction(isStaff,self)||(self&&currentUser()?.id!==id)){toast('Esta operación no está disponible para esta cuenta.');return}
 openModal(`<span class="eyebrow">Revisión de eliminación</span><h2 id="delete-title">${self?'Eliminar mi cuenta':'Eliminar cuenta'}</h2><p>Revisa la cuenta antes de continuar:</p><div class="account-review"><strong>${esc(fullName(u))}</strong><span>${esc(u.email)}</span></div><ul class="effects-list"><li>La cuenta no podrá ingresar y saldrá del listado vigente.</li><li>Los pedidos y comprobantes históricos se conservarán.</li><li>En esta demostración, gestión puede restaurarla deshabilitada.</li></ul><p class="notice">Propuesta de eliminación lógica pendiente de incorporar al ERS. No se elimina ninguna cuenta real.</p><div class="dialog-actions"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="danger" onclick="confirmAccountDeletion(${isStaff},${id},${self})">Confirmar datos</button></div>`,'delete-title');
}
async function confirmAccountDeletion(isStaff,id,self){
 const u=(isStaff?state.staff:state.users).find(u=>u.id===id);
 if(!u||u.deleted||!allowedAccountAction(isStaff,self)||(self&&currentUser()?.id!==id))return;
 if(!await ask({title:'¿Eliminar esta cuenta?',text:`Se retirará el acceso de ${u.email}. Sus pedidos históricos se conservarán.`,action:'Eliminar cuenta'}))return;
 if(!commit(()=>{u.deleted=true;u.active=false;u.deletedAt=new Date().toISOString();if(state.currentUserId===id){state.currentUserId=null;state.cart={}}}))return;
 closeModal();peopleDeletedView=false;render();toast('Cuenta eliminada de la sesión. Los pedidos históricos se conservan.');
}
async function restoreAccount(isStaff,id){
 const u=(isStaff?state.staff:state.users).find(u=>u.id===id);
 if(!u?.deleted||!allowedAccountAction(isStaff))return;
 if(!await ask({title:'Restaurar cuenta',text:`Restaurar ${u.email} como cuenta deshabilitada. Deberás habilitarla para que pueda ingresar.`,action:'Confirmar datos'}))return;
 if(!await ask({title:'¿Restaurar esta cuenta?',text:'La restauración no habilita el acceso automáticamente.',action:'Restaurar cuenta'}))return;
 if(commit(()=>{u.deleted=false;u.active=false;delete u.deletedAt})){render();toast('Cuenta restaurada y deshabilitada.')}
}
function checkoutSteps(step){return `<ol class="checkout-steps" aria-label="Etapas de compra">${['Carrito','Datos y pago','Confirmación'].map((name,i)=>`<li ${i===step?'aria-current="step"':''} class="${i<=step?'reached':''}"><span>${i+1}</span>${name}</li>`).join('')}</ol>`}
function carrito(){
 return `${checkoutSteps(0)}<div class="heading"><div><span class="eyebrow">Tu compra</span><h1>Carrito de compras</h1><p class="muted">${plural(cartCount())} en tu lista. Revisa las cantidades antes de continuar.</p></div><a class="text-button" href="#catalogo">Seguir comprando</a></div>${!cartCount()?`<div class="empty-state panel"><h2>Tu carrito está vacío</h2><p>Elige productos del catálogo para preparar tu compra.</p><button onclick="goClient('catalogo')">Explorar productos</button></div>`:`<div class="split checkout-layout"><section class="panel cart-items" aria-label="Productos en tu carrito">${state.products.filter(p=>state.cart[p.id]).map(p=>`<div class="cart-row"><div class="cart-photo">${productPhoto(p)}</div><div class="cart-product"><strong>${esc(p.name)}</strong><span class="muted">${esc(p.unit)} · ${money(p.price)} c/u</span><label class="sr-only" for="qty-${p.id}">Cantidad de ${esc(p.name)}</label><div class="cart-quantity"><button class="secondary" onclick="changeCartQuantity(${p.id},-1)" aria-label="Disminuir cantidad de ${esc(p.name)}" ${state.cart[p.id]<=1?'disabled':''}>−</button><input id="qty-${p.id}" type="number" min="1" max="${p.stock}" step="1" value="${state.cart[p.id]}" aria-describedby="qty-error-${p.id}" data-qty="${p.id}"><button class="secondary" onclick="changeCartQuantity(${p.id},1)" aria-label="Aumentar cantidad de ${esc(p.name)}" ${state.cart[p.id]>=p.stock?'disabled':''}>+</button></div><p class="field-error" id="qty-error-${p.id}" role="alert" hidden></p></div><div class="cart-subtotal"><strong>${money(p.price*state.cart[p.id])}</strong><button class="text-button" onclick="removeProduct(${p.id})">Quitar<span class="sr-only"> ${esc(p.name)}</span></button></div></div>`).join('')}<p class="cart-stock-note">La disponibilidad se comprueba nuevamente antes de pagar.</p></section>${receipt(true)}</div>`}`;
}
function changeCartQuantity(id,delta){const input=$(`#qty-${id}`);setQuantity(id,(state.cart[id]||0)+delta,input)}
function pago(){
 const u=currentUser();if(!cartCount()||!u)return `${checkoutSteps(1)}<div class="empty-state panel"><h1>Completa tu compra</h1><p>Necesitas productos y una cuenta habilitada para continuar.</p><button onclick="go('carrito')">Volver al carrito</button></div>`;
 return `${checkoutSteps(1)}<div class="heading"><div><span class="eyebrow">Revisión del pedido</span><h1>Datos y pago</h1><p class="muted">Revisa tu pedido antes de confirmar la compra de ejemplo.</p></div><a class="text-button" href="#carrito">Editar carrito</a></div><div class="split checkout-layout"><section class="panel checkout-data"><div class="checkout-block"><h2>Datos del cliente</h2><dl class="customer-grid"><div><dt>Nombre</dt><dd>${esc(fullName(u))}</dd></div><div><dt>Correo</dt><dd>${esc(u.email)}</dd></div><div><dt>Teléfono</dt><dd>${esc(u.phone)}</dd></div></dl></div><div class="checkout-block"><h2>Modalidad de entrega</h2><div class="delivery-choice"><span class="selection-dot" aria-hidden="true"></span><div><strong>Retiro en tienda</strong><p>Modalidad propuesta. Sucursal y horario por acordar.</p></div></div></div><div class="checkout-block"><h2>Método de pago</h2><div class="payment-provider"><strong>Webpay <span>Plus</span></strong><p>Pago alojado por Transbank en la implementación propuesta.</p></div><p class="notice">Esta pantalla simula el pago. No solicita datos bancarios ni realiza cobros.</p></div><p class="form-error" id="payment-error" role="alert" hidden></p><div class="action-group"><button onclick="pay(true)">Confirmar datos y continuar</button><button class="secondary" onclick="pay(false)">Probar pago rechazado</button></div></section>${receipt(false)}</div>`;
}
// Ventas de ejemplo con líneas completas. Totales, filtros, gráfico y CSV
// se calculan desde la misma colección, sin inventar cifras por filtro.
const reportView={tab:'sales',period:'week',category:'all',product:'all',stock:'all',ranking:'units'};
const REPORT_EXAMPLE_CUT='14/10/2026 03:00';
const sampleSales=(()=>{if(Array.isArray(state.reportSalesExample))return state.reportSalesExample;const out=[];for(let day=0;day<30;day++){
 const date=new Date(Date.UTC(2026,8,14+day)).toISOString().slice(0,10);
 for(let j=0;j<2+day%3;j++){
  const ids=[1+(day+j)%8,1+(day+j+3)%8];
  out.push({id:`V-${day}-${j}`,date,lines:ids.map((id,k)=>{const p=product(id);return {productId:p.id,name:p.name,category:p.cat,qty:1+(day+j+k)%4,price:p.price}})});
 }}commit(()=>state.reportSalesExample=out);return out})();
function reportRange(){const r=REPORTS[reportView.period];const iso=s=>s.split('/').reverse().join('-');return {...r,from:iso(r.start),to:iso(r.end)}}
function reportProducts(){return state.products.filter(p=>reportView.category==='all'||p.cat===reportView.category)}
function reportSelection(){
 const r=reportRange(),sales=sampleSales.filter(s=>s.date>=r.from&&s.date<=r.to).map(s=>({...s,lines:s.lines.filter(l=>(reportView.category==='all'||l.category===reportView.category)&&(reportView.product==='all'||l.productId===Number(reportView.product)))})).filter(s=>s.lines.length);
 const lines=sales.flatMap(s=>s.lines),total=lines.reduce((n,l)=>n+l.qty*l.price,0),units=lines.reduce((n,l)=>n+l.qty,0);
 const products=state.products.filter(p=>(reportView.category==='all'||p.cat===reportView.category)&&(reportView.product==='all'||p.id===Number(reportView.product))&&(reportView.stock==='all'||inventoryStatus(p).id===reportView.stock));
 const dates=[...new Set(sampleSales.filter(s=>s.date>=r.from&&s.date<=r.to).map(s=>s.date))];
 const trend=dates.map(date=>({date,total:sales.filter(s=>s.date===date).flatMap(s=>s.lines).reduce((n,l)=>n+l.qty*l.price,0)}));
 const ranking=[...new Set(lines.map(l=>l.productId))].map(id=>{const selected=lines.filter(l=>l.productId===id);return {id,name:selected[0].name,units:selected.reduce((n,l)=>n+l.qty,0),amount:selected.reduce((n,l)=>n+l.qty*l.price,0)}}).sort((a,b)=>reportView.ranking==='amount'?b.amount-a.amount:b.units-a.units);
 return {sales,lines,total,units,products,trend,ranking,average:sales.length?Math.round(total/sales.length):0};
}
function reportes(){
 return `<div class="heading report-heading"><div><span class="eyebrow">Administración</span><h1>Reportes de ventas e inventario</h1><p class="muted">Consulta tendencias y revisa la calidad de los datos de ejemplo.</p></div><button class="secondary" onclick="exportReport()">${uiIcon('download')} Exportar CSV</button></div><div class="report-subhead"><div class="section-tabs" role="tablist" aria-label="Tipo de reporte"><button id="tab-sales" role="tab" aria-selected="${reportView.tab==='sales'}" aria-controls="reportdata" onclick="setReportTab('sales')">Ventas</button><button id="tab-stock" role="tab" aria-selected="${reportView.tab==='stock'}" aria-controls="reportdata" onclick="setReportTab('stock')">Inventario</button></div><p class="report-updated">Corte histórico de ejemplo: <strong>${REPORT_EXAMPLE_CUT}</strong></p></div>
 <form class="report-filters panel" id="reportfilters"><div class="field"><label for="period">Período de ventas</label><select id="period" ${reportView.tab==='stock'?'disabled':''}>${Object.entries(REPORTS).map(([k,r])=>`<option value="${k}" ${k===reportView.period?'selected':''}>${r.start} – ${r.end}</option>`).join('')}</select></div><div class="field"><label for="report-category">Categoría</label><select id="report-category" onchange="reportCategoryOptions(this.value)"><option value="all">Todas las categorías</option>${categories.map(c=>`<option ${c===reportView.category?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field"><label for="report-product">Producto</label><select id="report-product"><option value="all">Todos los productos</option>${reportProducts().map(p=>`<option value="${p.id}" ${String(p.id)===reportView.product?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div>${reportView.tab==='stock'?`<div class="field"><label for="report-stock">Estado</label><select id="report-stock">${[['all','Todos los estados'],['available','Disponible'],['critical','Stock crítico'],['empty','Sin stock']].map(([v,t])=>`<option value="${v}" ${v===reportView.stock?'selected':''}>${t}</option>`).join('')}</select></div>`:''}<button type="submit">Aplicar filtros</button></form>
 <p class="report-context" id="report-context">${reportView.tab==='sales'?'Ventas ilustrativas calculadas desde pedidos de ejemplo. No incluyen compras simuladas durante esta sesión.':'Stock actual de la sesión. No representa el stock histórico del período de ventas.'}</p><div id="reportdata" role="tabpanel" aria-labelledby="tab-${reportView.tab}" aria-describedby="report-context"></div>`;
}
function reportCategoryOptions(category){$('#report-product').innerHTML='<option value="all">Todos los productos</option>'+state.products.filter(p=>category==='all'||p.cat===category).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}
function applyReportFilters(e){e.preventDefault();reportView.period=$('#period').value;reportView.category=$('#report-category').value;reportView.product=$('#report-product').value;reportView.stock=$('#report-stock')?.value||'all';reportPeriod=reportView.period;drawReport();toast('Filtros aplicados al reporte y su exportación.');}
function setReportTab(tab){reportView.tab=tab;render();$(`#tab-${tab}`).focus()}
function bindReport(){ $('#reportfilters').onsubmit=applyReportFilters;document.querySelectorAll('[role="tab"]').forEach(el=>el.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();setReportTab(e.key==='Home'?'sales':e.key==='End'?'stock':reportView.tab==='sales'?'stock':'sales')}});drawReport() }
function metric(label,value,note){return `<div class="metric"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`}
function salesChart(trend){
 const max=Math.max(1,...trend.map(t=>t.total));const coords=trend.map((t,i)=>[54+i*660/Math.max(1,trend.length-1),190-t.total/max*160]);const points=coords.map(c=>c.join(',')).join(' ');
 return `<svg class="sales-chart" viewBox="0 0 740 240" role="img" aria-label="Tendencia de ventas del período seleccionado. Consulta los valores en la tabla desplegable.">${[0,.5,1].map(n=>`<line x1="54" x2="714" y1="${190-n*160}" y2="${190-n*160}" stroke="#e3e9e2"/><text x="46" y="${194-n*160}" text-anchor="end" fill="#637064" font-size="12">${Math.round(max*n/1000)} mil</text>`).join('')}<polyline points="${points}" fill="none" stroke="#285332" stroke-width="3" stroke-linejoin="round"/>${coords.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="3" fill="#285332"><title>${trend[i].date}: ${money(trend[i].total)}</title></circle>`).join('')}${trend.filter((_,i)=>i===0||i===trend.length-1||i===Math.floor(trend.length/2)).map(t=>{const i=trend.indexOf(t);return `<text x="${coords[i][0]}" y="224" text-anchor="middle" fill="#637064" font-size="12">${t.date.slice(8)}/${t.date.slice(5,7)}</text>`}).join('')}</svg><details class="chart-values"><summary>Ver datos del gráfico</summary><div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Ventas CLP</th></tr></thead><tbody>${trend.map(t=>`<tr><td>${t.date}</td><td>${money(t.total)}</td></tr>`).join('')}</tbody></table></div></details>`;
}
function qualityReport(){openModal(`<span class="eyebrow">Calidad de datos</span><h2 id="quality-title">Registros pendientes de revisión</h2><p>Estos tres registros ilustrativos quedan fuera de los totales de ventas. Corregir el origen y validar su equivalencia precede a una nueva consolidación.</p><div class="tablewrap" tabindex="0" role="region" aria-label="Motivos de exclusión"><table><thead><tr><th>Registro</th><th>Motivo</th><th>Acción propuesta</th></tr></thead><tbody>${pendingRecords.map(x=>`<tr><td>${x.id}</td><td>${x.reason}</td><td>${x.action}</td></tr>`).join('')}</tbody></table></div><div class="dialog-actions"><button onclick="closeModal()">Cerrar</button></div>`,'quality-title')}
function drawReport(){
 const d=reportSelection(),critical=d.products.filter(p=>inventoryStatus(p).id==='critical').length,empty=d.products.filter(p=>p.stock===0).length;
 const quality=`<div class="quality-strip"><div>Datos históricos de ejemplo. Sin conexión a ventas reales.</div><button class="quality-link" onclick="qualityReport()">${pendingRecords.length} registros excluidos · Ver detalle</button></div>`;
 if(reportView.tab==='sales'){
 $('#reportdata').innerHTML=quality+`<div class="report-metrics">${metric('Ventas totales',money(d.total),'Selección aplicada')}${metric('Ticket promedio',money(d.average),'Promedio del importe seleccionado por compra')}${metric('Unidades vendidas',d.units,'Presentaciones completas')}${metric('Compras con ventas',d.sales.length,'Pedidos distintos de ejemplo')}</div>${!d.sales.length?`<section class="empty-state panel"><h2>Sin ventas para esta selección</h2><p>Prueba otro período, categoría o producto.</p></section>`:`<div class="report-charts"><section class="panel"><h2>Tendencia de ventas</h2><p class="muted">Importe diario del período seleccionado</p>${salesChart(d.trend)}</section><section class="panel"><div class="ranking-heading"><h2>Productos más vendidos</h2><div class="mini-switch" role="group" aria-label="Orden del ranking"><button aria-pressed="${reportView.ranking==='units'}" onclick="setRanking('units')">Unidades</button><button aria-pressed="${reportView.ranking==='amount'}" onclick="setRanking('amount')">Monto</button></div></div><ol class="ranking-list">${d.ranking.slice(0,5).map(x=>`<li><span>${esc(x.name)}</span><strong>${reportView.ranking==='amount'?money(x.amount):plural(x.units,'unidad','unidades')}</strong></li>`).join('')}</ol></section></div>`}`;
 }else{
 const total=d.products.reduce((n,p)=>n+p.stock,0),groups=categories.map(c=>({c,n:d.products.filter(p=>p.cat===c).reduce((n,p)=>n+p.stock,0)})).filter(x=>d.products.some(p=>p.cat===x.c)),max=Math.max(1,...groups.map(x=>x.n));
 $('#reportdata').innerHTML=`<div class="report-metrics">${metric('Productos',d.products.length,'Selección aplicada')}${metric('Unidades disponibles',total,'Stock de la sesión')}${metric('Stock crítico',critical,'Disponibilidad positiva hasta el mínimo')}${metric('Sin stock',empty,'Productos agotados')}</div><section class="panel"><h2>Stock por categoría</h2><p class="muted">Unidades actuales. Las barras comparan cantidades, no porcentajes respecto de una meta.</p><div class="bars">${groups.map(x=>`<div class="bar"><span>${esc(x.c)}</span><div class="track" aria-hidden="true"><div class="fill" style="width:${x.n/max*100}%"></div></div><strong>${x.n} un.</strong></div>`).join('')||'<p>No hay productos para los filtros seleccionados.</p>'}</div></section><section class="panel report-section"><h2>Detalle de inventario</h2><div class="tablewrap" tabindex="0" role="region" aria-label="Detalle de stock"><table><thead><tr><th>SKU</th><th>Producto</th><th>Stock</th><th>Mínimo</th><th>Estado</th></tr></thead><tbody>${d.products.map(p=>`<tr><td>${esc(p.sku)}</td><td>${esc(p.name)}</td><td>${p.stock}</td><td>${p.minStock??5}</td><td><span class="badge ${p.stock===0?'off':''}">${inventoryStatus(p).label}</span></td></tr>`).join('')||'<tr><td colspan="5">Sin productos para esta selección.</td></tr>'}</tbody></table></div></section>`;
 }
}
function setRanking(value){reportView.ranking=value;drawReport()}
function reportRows(){
 const d=reportSelection(),r=reportRange();const rows=[['Dumbo — reporte ilustrativo'],['Vista',reportView.tab==='sales'?'Ventas':'Inventario'],['Categoría',reportView.category],['Producto',reportView.product==='all'?'Todos':product(Number(reportView.product))?.name||''],['Origen',reportView.tab==='sales'?'Pedidos históricos de ejemplo':'Stock de la sesión']];
 if(reportView.tab==='sales')return [...rows,['Período',r.start,r.end],['Indicador','Valor'],['Ventas CLP',d.total],['Ticket promedio CLP',d.average],['Unidades vendidas',d.units],['Compras',d.sales.length],['Registros excluidos',pendingRecords.length],['Fecha','Ventas CLP'],...d.trend.map(t=>[t.date,t.total]),['Producto','Unidades','Monto CLP'],...d.ranking.map(x=>[x.name,x.units,x.amount]),['Registro excluido','Motivo','Acción'],...pendingRecords.map(x=>[x.id,x.reason,x.action])];
 return [...rows,['Estado',reportView.stock],['Productos',d.products.length],['Unidades disponibles',d.products.reduce((n,p)=>n+p.stock,0)],['Stock crítico',d.products.filter(p=>inventoryStatus(p).id==='critical').length],['Sin stock',d.products.filter(p=>p.stock===0).length],['SKU','Producto','Categoría','Stock','Mínimo','Estado'],...d.products.map(p=>[p.sku,p.name,p.cat,p.stock,p.minStock??5,inventoryStatus(p).label])];
}
function reportCsv(){return '\uFEFF'+reportRows().map(row=>row.map(csvCell).join(';')).join('\r\n')}
function exportReport(){const blob=new Blob([reportCsv()],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`dumbo-${reportView.tab}-${reportView.period}-ejemplo.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV exportado con la vista, filtros y valores mostrados.')}
